      if (e._cd <= 0 && peutArmer(e)) { e._st = 'mord'; e._stT = c.annonce || 0.5; e._tx = q.x; e._ty = q.y; armer(e, 'disque', e._stT, 'corps'); }
    } else if (e._st === 'mord') {
      e._stT -= dt;
      e._tx = q.x; e._ty = q.y;
      if (e._stT <= 0) {
        var J = N.joueuse;
        if (J && J.etat === 'vivant' && !J.invul() && O.d2(e.x, e.y, q.x, q.y) < 40 * 40 && J.len() > 4) {
