  }

  /* ============================ les passifs de contact ============================ */
  function actif(e) { return e && e.etat !== 'mort' && e.etat !== 'portail' && e.etat !== 'proie'; }
  function onKillGrappe(c) {
    var k = N.cartes && N.cartes.mods.grappe;
    if (!k || c.boss || !c.src || c.src.genre === 'decor') return;
    var gen = sourcesGrappe.get(c.src) || 0;
    if (gen >= R.passifs.grappe.generations) return;
    if (grappes.length >= R.passifs.effets.grappe.fileMax) { grappeSaturee++; return; }
    var p = R.passifs.grappe.niveaux[k - 1];
    var src = { genre: 'arme', type: 'grappe', id: c.id };
    sourcesGrappe.set(src, gen + 1);
    grappes.push({ x: c.x, y: c.y, r: p.rayon, dmg: p.degats, src: src, cibles: null, i: 0 });
  }
  function updGrappe() {
    var E = N.ennemis, cf = R.passifs.effets.grappe, nb = 0, touches = 0;
    if (!E) return;
    // Pas de récursion ni de kill émis ici : seul E.hit décide et journalise la mort.
    while (grappes.length && nb < cf.explosionsParPas && touches < cf.touchesParPas) {
      var g = grappes[0];
      if (!g.cibles) {
        g.cibles = E.pres(g.x, g.y, g.r);
        if (N.fx && N.fx.onde && N.fx.flashGate && N.fx.flashGate(Math.ceil(O.TAU * g.r * cf.ondeEpaisseur))) {
          N.fx.onde(g.x, g.y, cf.ondeDepart, g.r, O.ROSE, cf.ondeDuree, { epaisseur: cf.ondeEpaisseur });
        }
      }
      while (g.i < g.cibles.length && touches < cf.touchesParPas) {
        var e = g.cibles[g.i++];
        if (!actif(e) || O.d2(e.x, e.y, g.x, g.y) >= (g.r + e.r) * (g.r + e.r)) continue;
        touches++; E.hit(e, g.dmg, g.src);
      }
      if (g.i < g.cibles.length) break;
      grappes.shift(); nb++;
    }
  }

  // À appeler depuis la collision de tête, AVANT tuer('ennemi') (demande codex-06).
  // Le débit de réserve reste à la joueuse : ce module ne possède pas son réservoir.
  function percuter(e) {
    var J = N.joueuse, c = R.passifs.eperon;
    if (!J || !J.boost || !N.cartes || !N.cartes.mods.eperon || !actif(e) || e.boss || e.pv > c.pvMax) return false;
    if (J.reserve() < c.cout) return false;
    var p = J.tete, r = R.joueuse.rayonTete + e.r * R.mort.ennemi.facteurRayon;
    if (O.d2(p.x, p.y, e.x, e.y) >= r * r) return false;
    return N.ennemis.hit(e, e.pv, { genre: 'arme', type: 'eperon', id: null });
  }

  function updBraise(dt) {
    var k = N.cartes && N.cartes.mods.braise, J = N.joueuse, cf = R.passifs.effets.braise, i;
    if (!k || !N.ennemis) { braises.length = 0; braiseQueue = null; return; }
    for (i = braises.length - 1; i >= 0; i--) { braises[i].vie -= dt; if (braises[i].vie <= 0) braises.splice(i, 1); }
    var q = J.segPos(J.len());
    if (braiseQueue && O.d2(q.x, q.y, braiseQueue.x, braiseQueue.y) > cf.sautMax * cf.sautMax) braises.length = 0;
    var vie = R.f.traine(J.len(), k);
    if (!braiseQueue || O.d2(q.x, q.y, braiseQueue.x, braiseQueue.y) >= cf.pas * cf.pas || !braises.length) {
      if (braises.length >= cf.pointsMax) braises.shift();
      braises.push({ x: q.x, y: q.y, vie: vie }); braiseQueue = { x: q.x, y: q.y };
    }
    var L = N.ennemis.list;
    for (i = 0; i < L.length; i++) {
      var e = L[i]; if (!actif(e)) continue;
      var r = e.r + cf.largeur;
      for (var j = 0; j < braises.length; j++) {
        var b = braises[j];
        if (O.d2(e.x, e.y, b.x, b.y) < r * r) {
          // Une fois par ennemi et par pas, même si plusieurs points se superposent.
          // Source de contact de la joueuse existante ; type dédié « braise » demandé au gardien.
          N.ennemis.hit(e, R.passifs.braise.dps * dt, { genre: 'joueuse', type: 'tete', id: null });
          break;
        }
      }
    }
  }

  /* ============================ contrôle, sans champs privés d'ennemis ============================ */
  function source(a) { return { genre: 'arme', type: a, id: null }; }
  function ralentir(e, facteur, duree) {
    if (!facteur || e.boss || !actif(e)) return;
    var f = freins.get(e);
    if (!f) freins.set(e, { x: e.x, y: e.y, facteur: facteur, reste: duree });
    else { f.facteur = Math.min(f.facteur, facteur); f.reste = Math.max(f.reste, duree); f.x = e.x; f.y = e.y; }
  }
  function updFreins(dt) {
    freins.forEach(function (f, e) {
      f.reste -= dt;
      if (f.reste <= 0 || !actif(e)) { freins.delete(e); return; }
      var dx = e.x - f.x, dy = e.y - f.y, cf = R.armes.controle;
      // Ne jamais annuler une téléportation ni une sortie de portail.
      if (dx * dx + dy * dy < cf.sautMax * cf.sautMax) {
        e.x = f.x + dx * f.facteur; e.y = f.y + dy * f.facteur;
      }
      f.x = e.x; f.y = e.y;
    });
  }
  function anneauOnde(P, p) {
    var cf = R.armes.onde.dessin;
    ondeVis = { x: P.x, y: P.y, r: p.rayon, t: cf.duree,
      visible: !!(N.fx && N.fx.flashGate && N.fx.flashGate(Math.ceil(O.TAU * p.rayon * cf.epaisseur))) };
  }
  function updOnde(dt, P) {
    var cf = R.armes.onde, p = pal('onde'), E = N.ennemis;
    ondeT -= dt;
    if (p.auraDps && E) {
      var aura = E.pres(P.x, P.y, p.auraRayon);
      for (var ai = 0; ai < aura.length; ai++) if (actif(aura[ai])) E.hit(aura[ai], p.auraDps * dt * mul(), source('onde'));
    }
    if (ondeT > 0 || !E) return;
    ondeT += cf.mesures * R.temps.dureeMesure / cad();
    anneauOnde(P, p);
    var L = E.pres(P.x, P.y, p.rayon), A = O.A, marge = R.armes.controle.margeMur;
    for (var i = 0; i < L.length; i++) {
      var e = L[i]; if (!actif(e)) continue;
      var dx = e.x - P.x, dy = e.y - P.y, d = Math.sqrt(dx * dx + dy * dy), u = Math.max(0, 1 - d / p.rayon);
      E.hit(e, p.degats * (cf.degatsBord + (1 - cf.degatsBord) * u) * mul(), source('onde'));
      if (!e.boss && actif(e)) {
        // Les coordonnées monde sont publiques ; ni vitesse ni état interne réécrits.
        var pousse = p.poussee * (cf.pousseeBord + (1 - cf.pousseeBord) * u);
        if (d > 0) { e.x = O.clamp(e.x + dx / d * pousse, A.x0 + e.r + marge, A.x1 - e.r - marge);
          e.y = O.clamp(e.y + dy / d * pousse, A.y0 + e.r + marge, A.y1 - e.r - marge); }
        ralentir(e, p.ralenti, p.dureeRalenti);
      }
    }
    if (p.efface) {
      // Seul le producteur sait combien de tirs étaient vivants. Sans reçu, aucune cellule inventée.
      var n = E.effacerTirs(P.x, P.y, p.rayon);
      if (typeof n === 'number' && n > 0 && N.butin) {
        cellulesOnde += n * cf.conversion;
        var cellules = Math.floor(cellulesOnde);
        if (cellules > 0) { N.butin.lacher(P.x, P.y, cellules, { type: 'cellule', libre: true }); cellulesOnde -= cellules; }
      }
    }
    O.sfx('impact');
  }
  function updSillage(dt) {
    var cf = R.armes.sillage, p = pal('sillage'), J = N.joueuse, E = N.ennemis, i;
    for (i = sillage.length - 1; i >= 0; i--) { sillage[i].vie -= dt; if (sillage[i].vie <= 0) sillage.splice(i, 1); }
    var q = J.segPos(J.len());
    if (dernierSillage && O.d2(q.x, q.y, dernierSillage.x, dernierSillage.y) > cf.sautMax * cf.sautMax) sillage.length = 0;
    if (!dernierSillage || O.d2(q.x, q.y, dernierSillage.x, dernierSillage.y) >= cf.pas * cf.pas || !sillage.length) {
      if (sillage.length >= cf.pointsMax) sillage.shift();
      sillage.push({ x: q.x, y: q.y, vie: p.duree }); dernierSillage = { x: q.x, y: q.y };
    }
    if (!E) return;
    for (i = 0; i < E.list.length; i++) {
      var e = E.list[i]; if (!actif(e)) continue;
      var r = e.r + p.rayon;
      for (var j = 0; j < sillage.length; j++) {
        var b = sillage[j];
        if (O.d2(e.x, e.y, b.x, b.y) < r * r) {
          E.hit(e, p.dps * dt * mul(), source('sillage')); ralentir(e, p.ralenti, p.dureeRalenti); break;
        }
      }
    }
    if (p.efface && E.tirs.length) for (i = 0; i < sillage.length; i++) E.effacerTirs(sillage[i].x, sillage[i].y, p.rayon);
  }
  function updEpines(dt) {
    var k = N.cartes && N.cartes.mods.epines, J = N.joueuse, E = N.ennemis;
    if (!k || !E || (J.pouvoir.id === 'traversee' && J.pouvoir.etat === 'actif')) return;
    for (var i = 0; i < E.list.length; i++) {
      var e = E.list[i]; if (!actif(e)) continue;
      var h = J.hitTest(e.x, e.y, e.r);
      if (h.part === 'corps' || h.part === 'queue') {
        E.hit(e, R.passifs.epines.dps[k - 1] * dt, source('epines'));
        epinesT = R.armes.controle.dureeVisuelleEpines;
      }
    }
  }

  /* ============================ la mise à jour ============================ */
  function update(dt) {
    if (!S) S = N.S;
    var J = N.joueuse, P = J && J.tete, vivant = J && (J.etat === 'vivant' || J.etat === 'reapparition');
    var i, j, b, V = O.VUE, L = N.ennemis ? N.ennemis.list : [];
    if (st.salveSon > 0) st.salveSon -= dt;
    for (i = arcs.length - 1; i >= 0; i--) { arcs[i].t -= dt; if (arcs[i].t <= 0) arcs.splice(i, 1); }
    updGrappe();
    updFreins(dt);
    if (ondeVis) { ondeVis.t -= dt; if (ondeVis.t <= 0) ondeVis = null; }
    epinesT = Math.max(0, epinesT - dt);
    if (vivant && P) {
      updBraise(dt);
      if (st.niv.onde > 0) updOnde(dt, P);
      if (st.niv.sillage > 0) updSillage(dt); else { sillage.length = 0; dernierSillage = null; }
      updEpines(dt);
      updCanon(dt, P);
      if (st.niv.tourelles > 0) updTourelles(dt);
      if (st.niv.arc > 0) updArc(dt, P);
      if (st.niv.missiles > 0) updMissiles(dt, P);
      if (st.niv.drones > 0) updDrones(dt, P); else DR.length = 0;
      if (st.niv.minesQ > 0) updMines(dt);
    } else { st.rayonOn = false; DR.length = 0; braises.length = 0; braiseQueue = null; sillage.length = 0; dernierSillage = null; freins.clear(); ondeVis = null; }
    /* les tirs avancent et touchent */
    for (i = tirs.length - 1; i >= 0; i--) {
      b = tirs[i];
      b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt;
      if (b.life <= 0 || b.x < V.x - 4 || b.x > V.x + V.w + 4 || b.y < V.y - 4 || b.y > V.y + V.h + 4) { tirs.splice(i, 1); continue; }
      for (j = 0; j < L.length; j++) {
        var en = L[j];
        if (b._touches.indexOf(en) >= 0) continue;
        if (en._dead || en.etat === 'portail' || en._st === 'naissance' || en._proie) continue;
        var rr2 = en.r + 1.5;
        if (O.d2(b.x, b.y, en.x, en.y) < rr2 * rr2) {
          if (N.fx && N.fx.spark) O.safe('fx.spark', function () { N.fx.spark(b.x, b.y, -b.vx, -b.vy, 2, en.boss ? O.OS : O.ROSE); });
          N.ennemis.hit(en, b.dmg, SRC);
          b._touches.push(en);
          if (b._eclats) N.ennemis.zone(b.x, b.y, 8, 4 * b._eclats * mul(), SRC);
          if (b._perce > 0) b._perce--; else { tirs.splice(i, 1); }
          break;
        }
      }
    }
  }

  /* ============================ le dessin : montures sur le corps (sous le serpent), tirs, arcs, mines, drones ============================ */
  function px(x, y, c) { N.gfx.px(Math.round(x), Math.round(y), c); }
  function drawMontures() {
    var J = N.joueuse, len = J.len(), i, g = N.gfx, f = FL;
    if (st.niv.tourelles > 0) {
      var p = pal('tourelles'), n = Math.min(p.max || 4, Math.floor(len / (p.parSegments || 8)));
      for (i = 0; i < n; i++) {
        var k = Math.max(2, Math.round((i + 0.5) * len / n)), cote = (i & 1) ? 1 : -1;
        flanc(k, cote, f);
        g.rect(Math.round(f.x) - 1, Math.round(f.y) - 1, 3, 3, O.CYANP);                       // module 3 × 3 sur la perle
        px(f.x + f.nx * 2, f.y + f.ny * 2, O.CYAN); px(f.x + f.nx * 3, f.y + f.ny * 3, O.CYAN);  // canon de 2 px
      }
    }
    if (st.niv.arc > 0) {
      var q = J.segPos(len);
      g.rect(Math.round(q.x) - 1, Math.round(q.y) - 1, 3, 3, O.CYAN); px(q.x, q.y, O.CYANP);    // électrode de queue
    }
    if (st.niv.missiles > 0) {
      flanc(3, 1, f); g.rect(Math.round(f.x), Math.round(f.y), 1, 2, O.CYANP); px(f.x + f.nx, f.y + f.ny, O.CYAN);
      flanc(3, -1, f); g.rect(Math.round(f.x), Math.round(f.y), 1, 2, O.CYANP); px(f.x + f.nx, f.y + f.ny, O.CYAN);
    }
    if (st.niv.minesQ > 0) { var t = J.segPos(len); px(t.x, t.y, O.CYANP); px(t.x, t.y + 1, O.CYAN); px(t.x + 1, t.y, O.CYAN); }
  }
  function drawArc(a) {
    var g = N.gfx, p = a.pts, i;
    for (i = 0; i + 3 < p.length; i += 2) {
      var x0 = p[i], y0 = p[i + 1], x1 = p[i + 2], y1 = p[i + 3], mx = (x0 + x1) / 2 + (((i * 7) & 3) - 1.5), my = (y0 + y1) / 2 + (((i * 5) & 3) - 1.5);
      g.line(x0, y0, mx, my, O.CYAN); g.line(mx, my, x1, y1, O.CYAN);
      px(mx, my, O.CYANP);
    }
    for (i = 2; i + 1 < p.length; i += 2) g.rect(Math.round(p[i]) - 1, Math.round(p[i + 1]) - 1, 3, 3, O.OS);        // nœud d'os de 3 × 3 à chaque impact
  }
  function draw() {
    var f = Math.floor(O.T.ak * 12), g = N.gfx, i;
    if (!S) S = N.S;
    var J = N.joueuse;
    var cs = R.armes.sillage;
    for (i = 0; i < sillage.length; i++) {
      var si = sillage[i], sx = Math.round(si.x), sy = Math.round(si.y);
      if (N.pal.dither(sx, sy, cs.intensite * si.vie / pal('sillage').duree)) g.px(sx, sy, O.AMBRE);
    }
    if (J && st.niv.onde > 0 && ondeT <= R.armes.onde.telegraphe) {
      var po = pal('onde'), cf = R.armes.onde;
      g.ring(J.tete.x, J.tete.y, cf.dessin.depart + (po.rayon - cf.dessin.depart) * Math.max(0, ondeT / cf.telegraphe), O.AMBRE, cf.dessin.intensite);
    }
    if (ondeVis && ondeVis.visible) {
      var od = R.armes.onde.dessin;
      g.ring(ondeVis.x, ondeVis.y, od.depart + (ondeVis.r - od.depart) * (1 - ondeVis.t / od.duree), O.OS, od.intensite * ondeVis.t / od.duree);
    }
    if (J && N.cartes && N.cartes.mods.epines) {
      var ce = R.passifs.epines;
      for (i = ce.dessinPas; i < J.len(); i += ce.dessinPas) {
        flanc(i, (Math.floor(i / ce.dessinPas) & 1) ? -1 : 1, FL);
        g.line(FL.x, FL.y, FL.x + FL.nx * ce.dessinLongueur, FL.y + FL.ny * ce.dessinLongueur, epinesT > 0 ? O.AMBRE : O.ACIER);
      }
    }
    // Braises stables, sans clignotement : seulement une ligne de pixels ambre tramés.
    var cb = R.passifs.effets.braise;
    for (i = 0; i < braises.length; i++) {
      var br = braises[i], bx = Math.round(br.x), by = Math.round(br.y);
      if (N.pal.dither(bx, by, cb.intensite)) g.px(bx, by, O.AMBRE);
    }
    if (J && (J.etat === 'vivant' || J.etat === 'reapparition')) drawMontures();
    for (i = 0; i < mines.length; i++) {
      var m = mines[i], arme = m.t >= 0.4, bat = (Math.floor(O.T.ak * 4) & 1) === 1, x = Math.round(m.x), y = Math.round(m.y), cm = arme ? O.CYAN : O.INDIGO;
      if (m.vie < 2 && (f & 1)) continue;
      g.line(x - 2, y, x, y - 2, cm); g.line(x, y - 2, x + 2, y, cm); g.line(x + 2, y, x, y + 2, cm); g.line(x, y + 2, x - 2, y, cm);
      px(x, y, arme && bat ? O.CYANP : O.INDIGO);
      if (m.asp >= 0) g.ring(x, y, 30 * (1 - m.asp / 0.45), O.CYANP, 0.6);
    }
    for (i = 0; i < tirs.length; i++) {
      var b = tirs[i];
      if (b.kind === 'd' || b.kind === 't') { px(b.x, b.y, O.CYANP); px(b.x - b.vx * 0.01, b.y - b.vy * 0.01, O.CYAN); continue; }
      if (b.kind === 'l') { g.line(b.x - b.vx * 0.02, b.y - b.vy * 0.02, b.x, b.y, O.CYAN); px(b.x, b.y, O.CYANP); continue; }
      if (b._gros) { g.line(b.x - b.vx * 0.016, b.y - b.vy * 0.016, b.x, b.y, O.AMBRE); g.rect(b.x - 1, b.y - 1, 2, 2, O.JAUNE); }
      else O.put(O.sp('tir:' + O.dir16(b.a), f), b.x, b.y);
    }
    for (i = 0; i < missiles.length; i++) {
      var q = missiles[i], c = Math.cos(q.a), s = Math.sin(q.a);
      px(q.x, q.y, O.CYANP); px(q.x - c, q.y - s, O.CYAN); px(q.x - c * 2, q.y - s * 2, O.CYAN);
      px(q.x - c * 4, q.y - s * 4, (f & 1) ? O.INDIGO : O.CYAN);
      if (q.e && !q.e._dead && st.niv.missiles >= 4) { var w = O.T.ak * 6; for (var k = 0; k < 4; k++) px(q.e.x + Math.cos(w + k * 1.5708) * 6, q.e.y + Math.sin(w + k * 1.5708) * 6, O.CYANP); }
    }
    for (i = 0; i < arcs.length; i++) drawArc(arcs[i]);
    if (st.rayonOn) {                                      // le rayon : centre cyan pâle, bords cyan, paquets d'os qui filent
      g.line(BX0, BY0, BX1, BY1, O.CYANP);
      var dx = BX1 - BX0, dy = BY1 - BY0, ln = Math.sqrt(dx * dx + dy * dy) || 1, nx = -dy / ln, ny = dx / ln;
      g.line(BX0 + nx, BY0 + ny, BX1 + nx, BY1 + ny, O.CYAN); g.line(BX0 - nx, BY0 - ny, BX1 - nx, BY1 - ny, O.CYAN);
      for (i = 0; i < 4; i++) { var u = ((O.T.ak * 3 + i / 4) % 1); px(BX0 + dx * u, BY0 + dy * u, O.OS); }
    }
    for (i = 0; i + 1 < DR.length; i += 2) {                // le drone : satellite de 5 × 5 à œil cyan pâle
      var xx = Math.round(DR[i]), yy = Math.round(DR[i + 1]);
      g.rect(xx - 2, yy - 2, 5, 5, O.CYAN); g.rect(xx - 1, yy - 1, 3, 3, O.NUIT); px(xx, yy, O.CYANP);
    }
    var pd = pal('drones');
    if (DR.length >= 4 && (pd.filin || pd.anneau)) {
      var nd = DR.length / 2, ann = !!pd.anneau;
      for (i = 0; i < (ann ? nd : nd - 1); i++) {
        var a0 = i * 2, a1 = ((i + 1) % nd) * 2, ddx = DR[a1] - DR[a0], ddy = DR[a1 + 1] - DR[a0 + 1], ll = Math.max(1, Math.sqrt(ddx * ddx + ddy * ddy));
        for (var z = 0; z < ll; z += ann ? 2 : 3) px(DR[a0] + ddx * z / ll, DR[a0 + 1] + ddy * z / ll, O.CYANP);
      }
    }
  }

  /* ---- les consommateurs (rang 50) ---- */
  if (N.ev) {
    N.ev.on('kill', 50, onKillGrappe, '74-arsenal');
    N.ev.on('mort', 50, function () {
      st.chute = descendre(); grappes.length = 0; braises.length = 0; braiseQueue = null;
      sillage.length = 0; dernierSillage = null; freins.clear(); ondeVis = null;
    }, '74-arsenal');
    N.ev.on('carte', 50, function (c) {
      if (!c) return;
      if (c.id === 'canon') monter('canon');
      else if (N.ids.armes.indexOf(c.id) >= 0) monter(c.id);
      else if (c.id === 'cadence' && !(N.cartes && N.cartes.mods)) st.cad *= 1.15;       // repli : sans N.cartes.mods
    }, '74-arsenal');
  }

  return {
    chute: function () { return st.chute; }, reset: reset, update: update, draw: draw, monter: monter, descendre: descendre, niveau: niveau, armes: armes,
    tirs: tirs, surcharger: surcharger, percuter: percuter,
    etat: function () { return { arcs: arcs.length, missiles: missiles.length, mines: mines.length, drones: DR.length / 2, tourelles: st.nT, rayon: st.rayonOn,
      grappes: grappes.length, grappeSaturee: grappeSaturee, braises: braises.length,
      sillage: sillage.length, ondeDans: ondeT, freins: freins.size, onde: ondeVis && { x: ondeVis.x, y: ondeVis.y, r: ondeVis.r, t: ondeVis.t } }; }
  };
})();

/* ===== 75-cartes.js — N.cartes : expérience, vivier, tirages, pitié, mods, textes calculés (§ 2.7, 2.9) =====

   Le SEUL émetteur des événements `niveau` et `carte` (§ 7.4). Il CONSOMME `ramassage` (rang 30) : une cellule vaut
   1 XP, un noyau 5 (N.R.butin.<type>.xp). Les seuils d'expérience sont cumulés (N.R.xp.seuils). Une montée de
   niveau n'ouvre jamais d'écran : elle attend le NETTOYAGE de la vague (79-jeu → N.ui.ouvrir('cartes') → main()).

   LA MAIN. main(n, { trophee, vague, rareGarantie }) rend au plus n identifiants, tous différents. Règles : la première
   main contient une arme neuve, un pouvoir débloqué et une carte de survie ; la pitié garantit une rare au moins tous
   les 3 écrans et une épique tous les 7 ; la main trophée n'a aucune commune et propose l'ULTIME d'une arme à un palier
   près ; les poids favorisent l'école choisie (× 1,7) et freinent une famille vierge après la 6ᵉ carte (× 0,6). Au plus
   4 armes et 1 pouvoir équipés ; RALENTI et REPLI n'entrent dans le vivier qu'une fois débloqués (N.score.deblocages).
   Le tirage vient du flux 'cartes' (jamais Math.random).

   « CHOISIS n » : main() décide combien de cartes se prennent sur CET écran (1 + les montées en attente, 3 au plus,
   N.R.cartes.choixMax) et rend les montées restantes à l'écran suivant. choix() le dit à N.ui.

   LES TEXTES sont calculés de N.R (jamais écrits en dur) : texte(id) -> { nom, l1, l2, tag, rarete, palier, prises, max }.
   l1 et l2 tiennent en 19 caractères, le nom en 14 (N.R.cartes.texte).

   Interface (§ 7.8) : reset(), xp(n), niveauxEnAttente(), main(n, opts), choisir(id), prises(), texte(id), mods.
   Ajouts : niveau(), choix(), pouvoir(), armes() -> [{ id, palier }], palierDe(id), rarete(id), ecrans(), vivier(), pris().
   → demandes.md : ces ajouts attendent leur ligne dans CONTRAT.md. */
N.cartes = (function () {
  'use strict';
  var O = N.outils, R = N.R;
  var ARMES = ['canon', 'tourelles', 'arc', 'missiles', 'drones', 'minesQ', 'onde', 'sillage'];
  var POUVOIRS = ['traversee', 'ralenti', 'repli'];
  var ULTIMES = ['RAYON', 'BORDÉE', 'ORAGE', 'NUÉE', 'ANNEAU', 'SINGULARITÉ', 'DÉFERLANTE', 'MUR'];
  var S = null;
  var m = {                                       // l'état de la partie
    xp: 0, niveau: 0, attente: 0, prises: {}, equipees: ['canon'], pouvoir: null, nb: 0, ecrans: 0, sansRare: 0, sansEpique: 0,
    famille: {}, courante: [], choixEcran: 1, derniereVague: 0, repitJusqua: 0
  };
  var MODS = {};                                  // le même objet pour toute la partie, lu par les autres modules
  function cfg() { return R.cartes; }
  function liste(id) { return R.cartes.liste[id]; }
  function estArme(id) { return ARMES.indexOf(id) >= 0; }
  function estPouvoir(id) { return POUVOIRS.indexOf(id) >= 0; }

  /* ============================ la partie ============================ */
  function recalcMods() {
    var P = R.passifs, p = m.prises, base = P.mods, k;
    MODS.degats = 1 + P.puissance.parPrise * (p.puissance || 0);
    MODS.cadence = 1 + P.cadence.parPrise * (p.cadence || 0);
    k = Math.min(p.aimant || 0, P.aimant.rayons.length - 1);
    MODS.aimant = (p.aimant || 0) ? P.aimant.rayons[k] : base.aimant;
    MODS.lenMax = base.lenMax + ((R.longueur && R.longueur.parCroissance) || P.croissance.lenMax) * (p.croissance || 0);
    MODS.reparation = Math.min(2, p.reparation || 0);
    MODS.bouclier = Math.min(1, p.bouclier || 0);
    MODS.eperon = !!p.eperon;
    MODS.grappe = Math.min(2, p.grappe || 0);
    MODS.sangFroid = !!p.sangFroid;
    MODS.braise = Math.min(2, p.braise || 0);
    MODS.perforation = Math.min(P.perforation.prises, p.perforation || 0) * P.perforation.parPrise;
    MODS.surtension = Math.min(P.surtension.prises, p.surtension || 0);
    MODS.epines = Math.min(P.epines.prises, p.epines || 0);
  }
  function reset() {
    S = N.S;
    m.xp = 0; m.niveau = 0; m.attente = 0; m.prises = {}; m.equipees = ['canon']; m.pouvoir = null; m.nb = 0; m.ecrans = 0;
    m.sansRare = 0; m.sansEpique = 0; m.famille = {}; m.courante = []; m.choixEcran = 1; m.derniereVague = 0;
    m.repitJusqua = 0;
    recalcMods();
  }

  /* ============================ l'expérience ============================ */
  function xp(n) {
    if (!(n > 0)) return m.niveau;
    var seuils = R.xp.seuils, avant = m.niveau;
    m.xp += n;
    while (m.niveau < seuils.length && m.xp >= seuils[m.niveau]) {
      m.niveau++; m.attente++;
      if (N.ev) N.ev.emit('niveau', { niveau: m.niveau, enAttente: m.attente });
    }
    return m.niveau - avant;
  }
  function niveauxEnAttente() { return m.attente; }

  // Raccord public préparé pour 70-joueuse : vérifier AVANT une coupe, armer APRÈS une coupe effective.
  // Répit commun de survie, pas une nouvelle carte absente du registre figé de 03-socle.
  function apresCoupe() { m.repitJusqua = O.T.t + R.passifs.effets.repit.duree; }
  function repitActif(cause) { return cause !== 'mur' && O.T.t < m.repitJusqua; }

  /* ============================ la rareté et les paliers ============================ */
  function prisesMax(id) { return liste(id).prises; }
  function palierDe(id) { return (m.prises[id] || 0) + (id === 'canon' ? 1 : 0); }        // palier actuel : 0 = pas encore pris
  /* le palier que la carte donnerait, de 0 (I) à 3 (ULTIME) dans R.armes.<id>.paliers */
  function indexSuivant(id) { return id === 'canon' ? (m.prises.canon || 0) + 1 : (m.prises[id] || 0); }   // 0..3 dans R.armes.<id>.paliers
  function rarete(id) {
    if (estArme(id)) return cfg().rareteArme[Math.min(3, indexSuivant(id))];
    return liste(id).rarete;
  }
  function rang(r) { return r === 'commune' ? 0 : r === 'rare' ? 1 : r === 'epique' ? 2 : 3; }

  /* ============================ le vivier ============================ */
  function debloque(id) {
    var d = N.score && N.score.deblocages ? N.score.deblocages : [];
    return d.indexOf(id) >= 0;
  }
  function eligible(id) {
    // Le registre est gelé et appartient au socle : aucune carte inconnue sur le bus.
    if (!liste(id) || (N.ids && N.ids.cartes.indexOf(id) < 0)) return false;
    var k = m.prises[id] || 0;
    if (k >= prisesMax(id)) return false;
    var req = liste(id).prerequis;
    if (req && !req.some(function (r) { return palierDe(r.id) >= r.min; })) return false;
    if (estArme(id) && k === 0 && id !== 'canon' && m.equipees.length >= cfg().main.armesMax) return false;
    if (estPouvoir(id)) {
      if (m.pouvoir === id) return false;
      if ((id === 'ralenti' || id === 'repli') && !debloque(id)) return false;
    }
    return true;
  }
  function vivier() {
    var ids = (N.ids && N.ids.cartes) || Object.keys(cfg().liste), out = [];
    for (var i = 0; i < ids.length; i++) if (eligible(ids[i])) out.push(ids[i]);
    return out;
  }

  /* ============================ les tirages ============================ */
  function poids(id) {
    var c = cfg(), w = c.poids.rarete[rarete(id)], f = liste(id).famille, nf = m.famille[f] || 0;
    if (nf >= c.poids.ecoleCartes) w *= c.poids.ecole;
    else if (nf === 0 && m.nb > c.poids.viergeApres) w *= c.poids.vierge;
    // Une passive appelle la montée suivante de son arme et réciproquement.
    for (var arme in c.appels) {
      var passive = c.appels[arme];
      if ((id === arme && m.prises[passive]) || (id === passive && palierDe(arme) > 0)) { w *= c.poids.appel; break; }
    }
    return w;
  }
  function tirer(pool) {
    var tot = 0, i;
    for (i = 0; i < pool.length; i++) tot += poids(pool[i]);
    var r = O.rf('cartes') * tot;
    for (i = 0; i < pool.length; i++) { r -= poids(pool[i]); if (r <= 0) return i; }
    return pool.length - 1;
  }
  function retirer(pool, id) { var i = pool.indexOf(id); if (i >= 0) pool.splice(i, 1); }
  function tailleMain(choix) { return R.f && R.f.tailleMain ? R.f.tailleMain(choix) : Math.min(5, 2 + choix); }

  /* main(n, opts) : voir l'en-tête. n absent : la taille de la main pour le nombre de choix de cet écran. */
  function main(n, opts) {
    opts = opts || {};
    var c = cfg(), pool = vivier(), hand = [], i, id;
    m.choixEcran = Math.max(1, Math.min(c.choixMax, 1 + m.attente));
    m.attente -= m.choixEcran - 1;
    if (!(n > 0)) n = tailleMain(m.choixEcran);
    m.derniereVague = opts.vague || m.derniereVague;
    function prendre(id) { hand.push(id); retirer(pool, id); }
    function parmi(f) { var l = pool.filter(f); return l.length ? l[Math.min(l.length - 1, (O.rf('cartes') * l.length) | 0)] : null; }

    if (opts.trophee) {
      /* aucune commune ; l'ULTIME d'une arme à un palier près quand il y en a une */
      var ult = parmi(function (x) { return estArme(x) && rarete(x) === 'ultime'; });
      if (ult) prendre(ult);
      pool = pool.filter(function (x) { return rarete(x) !== 'commune'; });
    } else if (m.ecrans === 0) {
      /* la première main : une arme neuve, un pouvoir débloqué, une carte de survie */
      var a = parmi(function (x) { return estArme(x) && x !== 'canon' && !(m.prises[x] > 0); }); if (a) prendre(a);
      var p = parmi(function (x) { return estPouvoir(x); }); if (p) prendre(p);
      var sv = parmi(function (x) { return c.premiereMain.survie.indexOf(x) >= 0; }); if (sv) prendre(sv);
    }
    /* la pitié : une rare au moins tous les 3 écrans, une épique au moins tous les 7 */
    function aRare(r) { for (var j = 0; j < hand.length; j++) if (rang(rarete(hand[j])) >= r) return true; return false; }
    var forceEp = m.sansEpique >= c.pitie.epique - 1, forceRa = m.sansRare >= c.pitie.rare - 1 || !!opts.rareGarantie;
    if (forceEp && !aRare(2)) { id = parmi(function (x) { return rang(rarete(x)) >= 2; }); if (id) prendre(id); }
    if (forceRa && !aRare(1)) { id = parmi(function (x) { return rang(rarete(x)) >= 1; }); if (id) prendre(id); }
    while (hand.length < n && pool.length) prendre(pool[tirer(pool)]);
    if (hand.length > n) hand.length = n;
    /* l'ordre à l'écran est mélangé, pas celui du tirage (flux 'cartes') */
    for (i = hand.length - 1; i > 0; i--) { var j2 = (O.rf('cartes') * (i + 1)) | 0, t = hand[i]; hand[i] = hand[j2]; hand[j2] = t; }
    m.sansRare = aRare(1) ? 0 : m.sansRare + 1;
    m.sansEpique = aRare(2) ? 0 : m.sansEpique + 1;
    m.ecrans++;
    m.courante = hand.slice();
    return hand;
  }

  /* ============================ le choix ============================ */
  function choisir(id) {
    if (!id || !eligible(id)) return null;
    var k = (m.prises[id] || 0) + 1;
    if (k > prisesMax(id)) return null;
    m.prises[id] = k; m.nb++;
    var f = liste(id).famille; m.famille[f] = (m.famille[f] || 0) + 1;
    if (estArme(id) && m.equipees.indexOf(id) < 0) m.equipees.push(id);
    if (estPouvoir(id)) m.pouvoir = id;
    recalcMods();
    if (N.ev) N.ev.emit('carte', { id: id, niveau: k });
    return k;
  }

  /* ============================ les textes, calculés de N.R ============================ */
  function f1(x) { return String(Math.round(x * 100) / 100).replace('.', ','); }
  function palierArme(id, i) { var p = R.armes[id].paliers; return p[Math.min(p.length - 1, i)]; }
  function cadenceCanon(niv) { var p = R.armes.canon.paliers[Math.max(0, Math.min(3, niv))]; return p.cadence || p.tics || 0; }
  function texteArme(id, i) {
    var p = palierArme(id, i), pr = i > 0 ? palierArme(id, i - 1) : null, a = R.armes[id], l1, l2;
    if (id === 'canon') {
      if (i === 1) { l1 = '2 BOUCHES ALTERNÉES'; l2 = f1(pr.cadence) + ' → ' + f1(p.cadence) + ' TIRS/S'; }
      else if (i === 2) { l1 = '2 LANCES PERÇANTES'; l2 = 'DÉGÂTS ' + pr.degats + ' → ' + p.degats; }
      else { l1 = 'RAYON CONTINU'; l2 = p.degats + ' DÉG · ' + p.tics + '/S'; }
    } else if (id === 'tourelles') {
      l1 = '1 TOUS LES ' + p.parSegments + ' SEG.'; l2 = p.max + ' AU PLUS · ' + f1(p.cadence) + '/S';
      if (i === 2) l1 = 'RAFALES DE ' + p.rafale + ' · 1/' + p.parSegments;
      if (i === 3) { l1 = '1 TOUS LES ' + p.parSegments + ' SEG.'; l2 = p.max + ' MAX · SALVE'; }
    } else if (id === 'arc') {
      l1 = p.arcs + (p.arcs > 1 ? ' ARCS · ' : ' ARC · ') + p.sauts + ' SAUTS'; l2 = p.degats + ' DÉG / ' + f1(p.periode) + ' S';
    } else if (id === 'missiles') {
      l1 = p.missiles + ' MISSILES' + (p.sousMunitions ? ' + ' + p.sousMunitions : ''); l2 = p.degats + ' DÉG / ' + f1(p.periode) + ' S';
    } else if (id === 'drones') {
      l1 = p.drones + (p.drones > 1 ? ' DRONES' : ' DRONE') + (p.interception ? ' · BOUCLIER' : ''); l2 = 'TIR ' + f1(a.cadence) + '/S · ' + a.degats + ' DÉG';
    } else if (id === 'onde') {
      l1 = p.degats + ' DÉG · ' + p.rayon + ' PX'; l2 = p.efface ? 'EFFACE LES TIRS' : 'REPOUSSE AUTOUR';
    } else if (id === 'sillage') {
      l1 = f1(p.dps) + ' DÉG/S · QUEUE'; l2 = p.efface ? 'MUR ANTI-TIRS' : f1(p.duree) + ' S DE TRACE';
    } else {
      l1 = '1 MINE / ' + f1(p.periode) + ' S'; l2 = 'SOUFFLE ' + p.souffle + ' PX · ' + p.degats;
    }
    return [l1, l2];
  }
  function textePassif(id) {
    var P = R.passifs, k = m.prises[id] || 0, a = P[id], l1, l2, i = Math.min(k, (a && a.prises ? a.prises : 1) - 1);
    switch (id) {
      case 'puissance': l1 = 'DÉGÂTS DES ARMES'; l2 = '×' + f1(1 + a.parPrise * k) + ' → ×' + f1(1 + a.parPrise * (k + 1)); break;
      case 'cadence':
        var c0 = cadenceCanon((m.prises.canon || 0)); l1 = 'CADENCE'; l2 = f1(c0 * (1 + a.parPrise * k)) + ' → ' + f1(c0 * (1 + a.parPrise * (k + 1))) + ' TIRS/S'; break;
      case 'aimant': l1 = 'RAYON D\'AIMANT'; l2 = (k ? a.rayons[k] : P.mods.aimant) + ' → ' + a.rayons[Math.min(k + 1, a.rayons.length - 1)] + ' PX'; break;
      case 'croissance':
        var pc = (R.longueur && R.longueur.parCroissance) || a.segments;     // la valeur que 70-joueuse applique (→ demandes.md : le tableau § 2.9 dit +4)
        l1 = '+' + pc + ' SEGMENTS'; l2 = 'MAX ' + MODS.lenMax + ' → ' + (MODS.lenMax + a.lenMax); break;
      case 'reparation': l1 = 'REPOUSSE 1 SEGMENT PERDU'; l2 = 'TOUTES LES ' + a.periodes[i] + ' S'; break;
      case 'bouclier': l1 = 'ABSORBE UN COUP'; l2 = 'RECHARGE ' + a.recharge + ' S'; break;
      case 'eperon': l1 = 'EN ACCÉLÉRATION'; l2 = 'BROIE JUSQU\'À ' + a.pvMax + ' PV'; break;
      case 'grappe': l1 = 'KILL = EXPLOSION'; l2 = a.niveaux[i].rayon + ' PX · ' + a.niveaux[i].degats + ' DÉG'; break;
      case 'sangFroid': l1 = 'LA COUPE NE DIVISE'; l2 = 'PLUS LA CHAÎNE'; break;
      case 'perforation': l1 = 'TRAVERSE +' + a.parPrise + ' CIBLE'; l2 = 'TIRS NON EXPLOSIFS'; break;
      case 'surtension': l1 = '+' + a.sautsParPrise + ' SAUT PAR ARC'; l2 = 'PORTÉE +' + f1(a.porteeParPrise * 100) + ' %'; break;
      case 'epines': l1 = 'CONTACT DU CORPS'; l2 = a.dps[i] + ' DÉG / S'; break;
      default: l1 = 'TRAÎNÉE QUI BRÛLE'; l2 = i ? '+' + f1(a.traine2) + ' S DE TRAÎNÉE' : a.dps + ' DÉG / S'; break;
    }
    return [l1, l2];
  }
  function textePouvoir(id) {
    var a = R.pouvoirs[id];
    if (id === 'traversee') return [f1(a.duree) + ' S TRAVERSE TOUT', 'RECHARGE ' + a.recharge + ' S'];
    if (id === 'ralenti') return ['MONDE ×' + f1(a.monde) + ' · ' + f1(a.duree) + ' S', 'RECHARGE ' + a.recharge + ' S'];
    return ['LONGUEUR -' + Math.round(a.longueur * 100) + ' %', 'DÉGÂTS ×' + f1(a.degats) + ' · ' + a.duree + ' S'];
  }
  function romain(n) { return ['0', 'I', 'II', 'III', 'IV'][n] || String(n); }
  function texte(id) {
    var L = liste(id), k = m.prises[id] || 0, arme = estArme(id), pouv = estPouvoir(id), ls, tag, pal = 0;
    if (arme) {
      var i = indexSuivant(id); pal = i + 1;
      ls = texteArme(id, i);
      tag = (id !== 'canon' && k === 0) ? 'NOUVEAU' : (i >= 3 ? 'ULTIME' : 'NIV ' + romain(i + 1));
    } else if (pouv) { ls = textePouvoir(id); tag = m.pouvoir ? 'REMPLACE' : 'NOUVEAU'; pal = 1; }
    else { ls = textePassif(id); tag = k === 0 ? 'NOUVEAU' : 'NIV ' + (k + 1); pal = k + 1; }
    return { nom: N.ids.nom(id), l1: ls[0], l2: ls[1], tag: tag, rarete: rarete(id), palier: pal, prises: k, max: prisesMax(id),
      ultime: arme && indexSuivant(id) >= 3 ? ULTIMES[ARMES.indexOf(id)] : null, famille: L.famille,
      prerequis: L.prerequis || [], appelle: cfg().appels[id] || null };
  }

  /* ============================ les consommateurs ============================ */
  if (N.ev) {
    N.ev.on('ramassage', 30, function (c) {
      var b = R.butin && R.butin[c.type];
      if (b && b.xp) xp(b.xp);
    }, '75-cartes');
  }

  /* MODS : initialisé à la valeur de départ dès le chargement, pour être lisible avant le premier reset() */
  recalcMods();
  return {
    reset: reset, xp: xp, niveauxEnAttente: niveauxEnAttente, main: main, choisir: choisir, prises: function () { return m.prises; }, texte: texte,
    mods: MODS, apresCoupe: apresCoupe, repitActif: repitActif,
    niveau: function () { return m.niveau; }, choix: function () { return m.choixEcran; }, pouvoir: function () { return m.pouvoir; },
    armes: function () { return m.equipees.map(function (id) { return { id: id, palier: palierDe(id) }; }); },
    palierDe: palierDe, rarete: rarete, ecrans: function () { return m.ecrans; }, vivier: vivier, pris: function () { return m.nb; },
    courante: function () { return m.courante; }, xpTotal: function () { return m.xp; }
  };
})();

/* LE DÉFILÉ (§ 4.7) : bonus joué entre V3 et V4. Les planeurs ordinaires de
   N.ennemis portent le tir/LASSO et le score ; ce module produit leurs courbes,
   les rend inoffensifs et compte uniquement leurs vrais kills de joueuse.
   Aucun réglage local : nombres/durée/prime viennent de N.R.defile.
   Le raccord de la machine d'états est livré à part dans tools/codex-10/.
   API : demarrer(), update(dt), draw(), fini(), joue(), bilan(), prendreRare(), reset(). */
N.defile = (function () {
  'use strict';
  var O = N.outils, R = N.R, ids = {}, t = 0, groupes = 0, pris = 0;
  var actif = false, joue = false, termine = false, parfait = false, rare = false;
  function cfg() { return R.defile; }
  function journal(evt) {
    if (N.journal) N.journal('defile', { evt: evt, t: t, escadrilles: groupes, attrapes: pris, total: cfg().planeurs, parfait: parfait });
  }
  function publier() {
    if (N.S) N.S.defile = { actif: actif, t: t, duree: cfg().duree, escadrilles: groupes, attrapes: pris, total: cfg().planeurs, parfait: parfait };
  }
  function reset() {
    ids = {}; t = 0; groupes = 0; pris = 0;
    actif = joue = termine = parfait = rare = false; publier();
  }
