    function jeuNeuf() { if (!JOUE[et] || et === 'reapparition') { lancer(false); } O.geom(); lancerVague(1); N.ennemis.reset(); }
    if (nom === 'mur') { jeuNeuf(); N.joueuse.force({ x: O.A.x0 + 30, y: (O.A.y0 + O.A.y1) / 2, ang: Math.PI, trace: true }); return true; }
    if (nom === 'morsure') {
